func (c *EngineCommandCatalog) All() []*CommandSymbol {
	if c == nil {
		return nil
	}
	return append([]*CommandSymbol{}, c.all...)
}

// ServerCommandCatalog represents the generated single-command catalogs
// used by the non-engine server kinds in the pinned source.
type ServerCommandCatalog struct {
	ShowVersion *CommandSymbol
	all         []*CommandSymbol
}

var (
	AriaBridgeCommands     = newServerCommandCatalog(internal.AriaBridgeCommands.ShowVersion, internal.AriaBridgeCommands.All)
	ClusterManagerCommands = newServerCommandCatalog(internal.ClusterManagerCommands.ShowVersion, internal.ClusterManagerCommands.All)
	DataManagerCommands    = newServerCommandCatalog(internal.DataManagerCommands.ShowVersion, internal.DataManagerCommands.All)
)

func newServerCommandCatalog(showVersion *CommandSymbol, all []*CommandSymbol) *ServerCommandCatalog {
	return &ServerCommandCatalog{ShowVersion: showVersion, all: append([]*CommandSymbol{}, all...)}
}

func (c *ServerCommandCatalog) All() []*CommandSymbol {
	if c == nil {
		return nil
	}
	return append([]*CommandSymbol{}, c.all...)
}
